package oepul.o6_9

import rego.v1

applicant_form_ok if input.farm.applicant.form in {"natural", "registered_partnership"}

applicant_form_ok if {
	a := input.farm.applicant
	a.form in {"legal_person", "association"}
	nonnegative(a.public_share_percent)
	a.public_share_percent <= 25
}

operator_ok if {
	applicant_form_ok
	a := input.farm.applicant
	a.own_name_and_account == true
	a.control_of_land == true
	a.active_farmer == true
	a.agricultural_activity == true
	a.public_body_or_institution == false
}

size_ok if {
	is_number(input.farm.oepul_participation_year)
	input.farm.oepul_participation_year >= 2
}

size_ok if {
	input.farm.oepul_participation_year == 1
	nonnegative(input.land.austrian_protected_cultivation_ha)
	input.land.austrian_protected_cultivation_ha >= 0.5
}

size_ok if {
	input.farm.oepul_participation_year == 1
	nonnegative(input.land.austrian_minimum_size_area_ha)
	input.land.austrian_minimum_size_area_ha >= 1.5
}

crop_groups(name) := {r.group | some r in tables.crop_names; r.name == name; year >= r.from_year}

drought_exception(p) if {
	year == 2026
	p.land_use == "arable"
	p.country == "AT"
	p.drought_no_harvestable_crop == true
	p.heat_drought_sensitive == true
	p.normal_harvest in {"late_summer", "autumn"}
	some row in tables.drought_districts
	row.state == p.federal_state
	district_match(row.district, p)
}

district_match("alle Bezirke", _) := true
district_match(d, p) if d == p.district

harvest_met(p) if {
	nonnegative(p.harvested_removed_percent)
	p.harvested_removed_percent >= 85
	p.harvested_removed_percent <= 100
}

harvest_met(p) if drought_exception(p)

arable_care_ok(p) if {
	arable_or_protected(p)
	p.properly_sown == true
	p.annual_care == true
	harvest_met(p)
}

arable_or_protected(p) if {
	p.land_use == "arable"
	p.arable_forage == false
}

arable_or_protected(p) if p.protected_cultivation == true

modulation_factor := sum([portion |
	some row in tables.modulation
	hi := band_end(row, input.land.home_area_ha)
	width := max([0, hi - row.start])
	portion := width * row.factor
]) / input.land.home_area_ha if {
	input.land.home_area_ha > 0
}

band_end(row, ha) := ha if row.end == null

else := min([row.end, ha])

area_ceiling(group) := row.eur_per_ha if {
	some row in tables.area_caps
	row.group == group
	year >= row.from_year
	year <= row.through_year
}

sanction_schedule := {r.stage: v | some r in tables.sanctions; v := stage_value(r)}
stage_value(r) := r.from_2027 if year >= 2027

else := r.through_2026 if year >= 2023

loss_tolerance_ha(prior) := max([0.5, min([5, 0.05 * prior])]) if nonnegative(prior)

takeover_case if {
	t := annual.takeover
	t.event in {"dissolution", "division", "merger"}
	t.approved_by_ama == true
	t.online_application == true
}

upgrade_allowed(source, target) if {
	some r in tables.upgrades
	r.source == source
	r.target == target
	program_year
	year <= r.through_year
}

contract_group(name) := tables.contract_groups[name]
reduction_order := tables.reduction_order

combination_cell(a, b) := tables.combinations[a][b]
combination_note(n) := tables.combination_notes[n]

# Kontext zur Einzelfläche. Ein Minderungsbetrag ist in Anhang L nicht beziffert.
parcel_combination_ok(a, b, ctx) if {
	cell := combination_cell(a, b)
	cell != ""
	ctx.protected_pots_or_substrate == false
	landscape_condition(cell, ctx)
	vienna_ok({a, b}, ctx)
	pesticide_ok({a, b}, ctx)
	special_strip_ok({a, b}, ctx)
}

landscape_condition(cell, _) if cell != "x1)"
landscape_condition("x1)", ctx) if ctx.landscape_elements_only == true

vienna_ok(pair, _) if pair != {"8", "16"}

vienna_ok(pair, ctx) if {
	pair == {"8", "16"}
	ctx.vienna_humus == false
}

pesticide_ok(pair, _) if pair != {"1B", "16"}

pesticide_ok(pair, ctx) if {
	pair == {"1B", "16"}
	ctx.pesticide_waiver == false
}

special_strip_ok(_, ctx) if ctx.strip in {"none", "other"}

special_strip_ok(pair, ctx) if {
	ctx.strip == "BAW"
	ctx.landscape_elements_only == true
	"8" in pair
	count(pair & {"1A", "1B"}) == 1
}

special_strip_ok(pair, ctx) if {
	ctx.strip == "AG"
	ctx.landscape_elements_only == true
	"16" in pair
	count(pair & {"1A", "1B"}) == 1
}

combination_discount(a, b, ctx) if {
	parcel_combination_ok(a, b, ctx)
	combination_cell(a, b) == "a"
}

combination_discount(a, b, ctx) if {
	parcel_combination_ok(a, b, ctx)
	combination_cell(a, b) == "x3)"
	ctx.organism_supplement == true
}

grass_care_ok(p) if {
	p.mountain_hay_meadow == true
	p.full_cut_removed_within_two_years == true
}

grass_care_ok(p) if {
	p.mountain_hay_meadow == false
	grass_or_forage(p)
	p.full_cut_removed_this_year == true
}

grass_care_ok(p) if {
	p.mountain_hay_meadow == false
	grass_or_forage(p)
	p.fully_grazed_this_year == true
}

grass_or_forage(p) if p.land_use == "grassland"

grass_or_forage(p) if {
	p.land_use == "arable"
	p.arable_forage == true
}

conditionality_met if {
	input.farm.administration.conditionality_compliant == true
	input.farm.administration.social_conditionality_compliant == true
}

# Positive Feststellungen, auch wenn die übrigen Angaben unvollständig sind.
area_exclusions contains {"parcel_id": p.parcel_id, "reason": reason} if {
	some p in input.land.parcels
	some reason in parcel_reasons(p)
}

parcel_reasons(p) := {reason | some reason in ["Ausland", "MFA-Fläche fehlt", "Fehlidentifikation", "Nutzung", "Hauptnutzung", "Nationalpark", "Versuchsfläche", "OP", "Leistungsüberschneidung", "Infrastrukturauflage", "Verpflichtungsdauer"]; excluded_for(p, reason)}

excluded_for(p, "Ausland") if {
	is_string(p.country)
	p.country != "AT"
}

excluded_for(p, "MFA-Fläche fehlt") if p.payment_controls.claimed_for_measure == false
excluded_for(p, "Fehlidentifikation") if p.payment_controls.correctly_identified == false
excluded_for(p, "Nutzung") if p.payment_controls.use_code in tables.ineligible_uses
excluded_for(p, "Hauptnutzung") if p.payment_controls.primarily_agricultural == false
excluded_for(p, "Nationalpark") if p.payment_controls.national_park in {"Neusiedlersee", "Donau-Auen"}

excluded_for(p, "Nationalpark") if {
	is_string(p.payment_controls.national_park)
	p.payment_controls.national_park != ""
	p.payment_controls.national_park_relevant_obligations == true
}

excluded_for(p, "Versuchsfläche") if "VF" in p.payment_controls.mfa_codes

excluded_for(p, "OP") if {
	some code in p.payment_controls.mfa_codes
	code in {"OP", annual.measure_op_code}
	code != ""
}

excluded_for(p, "OP") if "OP" in p.payment_controls.mfa_codes
excluded_for(p, "Leistungsüberschneidung") if p.payment_controls.overlap_public_or_legal == true
excluded_for(p, "Infrastrukturauflage") if p.payment_controls.prescribed_infrastructure_use == true
excluded_for(p, "Verpflichtungsdauer") if p.payment_controls.full_period_compliance == false

takeover_area_ok if {
	takeover_case
	t := annual.takeover
	t.previous_participant == false
	in_year(t.date)
	t.date <= sprintf("%04d-04-%02d", [year, april_day])
	nonnegative(t.additional_ha)
	nonnegative(t.transferred_ha)
	t.additional_ha <= 0.5 * t.transferred_ha
}

payment_deadline := sprintf("%04d-06-30", [year + 1]) if program_year

advance_max_eur(expected) := expected * 0.75 if {
	nonnegative(expected)
	input.farm.administration.administrative_checks_complete == true
}

sanction_outcome := "Ausschluss und Rückforderung" if {
	input.farm.administration.graded_stage == "100"
	nonnegative(input.farm.administration.prior_full_reductions_in_contract)
	input.farm.administration.prior_full_reductions_in_contract >= 1
} else := sanction_schedule[input.farm.administration.graded_stage] if {
	input.farm.administration.graded_stage != "100"
} else := 100 if {
	input.farm.administration.graded_stage == "100"
	input.farm.administration.prior_full_reductions_in_contract == 0
}

management_exception(feature, measure) if {
	some row in tables.management_exceptions
	feature == row.feature
	measure in row.measures
	year <= object.get(row, "through_year", 2028)
	program_year
}

public_body_exception(measure) if {
	some row in tables.public_body_exceptions
	row.measure == measure
	year >= row.from_year
	year <= row.through_year
}

conversion_allowed(source, target, measure) if {
	some row in tables.permitted_conversions
	source in row.from
	target in row.to
	measure in object.get(row, "measures", [measure])
}

multiannual_term(first_year) := row.years if {
	some row in tables.long_terms
	row.start_year == first_year
}

package oepul.o6_9

import rego.v1

tables := data.o6_9_tables
year := input.farm.year
annual := input.o6_9

program_year if {
	year >= 2023
	year <= 2028
}

nonnegative(x) if {
	is_number(x)
	x >= 0
}

valid_date(d) if {
	regex.match(`^\d{4}-\d{2}-\d{2}$`, d)
	time.parse_rfc3339_ns(concat("", [d, "T00:00:00Z"])) != null
}

in_year(d) if {
	valid_date(d)
	startswith(d, sprintf("%04d-", [year]))
}

base_entry_ok if {
	program_year
	year <= 2027
	timely_prior_application(annual.base_application_date)
}

timely_prior_application(d) if {
	valid_date(d)
	d <= sprintf("%04d-12-31", [year - 1])
}

feed_entry_ok if {
	program_year
	year >= 2025
	annual.base_contract_active == true
	timely_prior_application(annual.feed_application_date)
}

april_day := 17 if year in {2023, 2028}

else := 15

mfa_timely if {
	program_year
	valid_date(annual.mfa_date)
	annual.mfa_date <= sprintf("%04d-04-%02d", [year, april_day])
}

withdrawn_in_year if in_year(annual.withdrawal_date)

rate(category) := row.eur if {
	some row in tables.rates
	row.category == category
	year >= row.from_year
	year <= row.through_year
}

# Eine Meldung je Verfahren entspricht dem bis zum Stichtag wirksamen Stand.
claimed_volume(category) := c.volume_m3 if {
	c := annual.claims[category]
	nonnegative(c.volume_m3)
	in_year(c.date)
	c.date <= sprintf("%04d-11-30", [year])
}

no_annual_claim if {
	annual.claims_complete == true
	is_object(annual.claims)
	every method, claim in annual.claims {
		method in {"trailing_hose", "trailing_shoe", "injection", "separation"}
		nonnegative(claim.volume_m3)
		in_year(claim.date)
	}
	not positive_claim
	no_feeding_participation
}

no_feeding_participation if {
	program_year
	year < 2025
}

no_feeding_participation if annual.feeding.participating == false

positive_claim if {
	some c in ["trailing_hose", "trailing_shoe", "injection", "separation"]
	claimed_volume(c) > 0
}

material_ok(e) if {
	e.material in {"slurry", "liquid_manure"}
	e.originally_liquid == true
}

material_ok(e) if {
	e.material == "digestate"
	e.originally_liquid == true
	e.substrate_proof == true
	is_array(e.substrates)
	count(e.substrates) > 0
	every s in e.substrates {
		checks := tables.substrates[s.name]

		# Das Merkblatt und die SRL weichen bei Maisquellwasser voneinander ab.
		s.name != "Maisquellwasser"
		every requirement in checks { requirement in s.confirmed }
	}
}

eligible_volume(e) := v if {
	material_ok(e)
	nonnegative(e.volume_m3)
	nonnegative(e.ineligible_water_m3)
	e.ineligible_water_m3 <= e.volume_m3
	v := e.volume_m3 - e.ineligible_water_m3
}

equipment_ok(e) if e.ownership == "own"

equipment_ok(e) if {
	e.ownership == "external"
	e.service_evidence == true
}

equipment_ok(e) if {
	e.ownership == "shared"
	e.inspectable_at_participant == true
	e.invoice_to_participants_available == true
}

spread_log_ok(e) if {
	in_year(e.date)
	is_string(e.parcel_id)
	e.parcel_id != ""
	is_string(e.material)
	e.method in {"trailing_hose", "trailing_shoe", "injection"}
	nonnegative(e.volume_m3)
	annual.spreading_chronological == true
}

group_log_ok(entries, recorded_ha) if {
	is_array(entries)
	count(entries) > 0
	first := entries[0]
	is_string(first.crop)
	valid_date(first.date)
	first.method in {"trailing_hose", "trailing_shoe", "injection"}
	nonnegative(first.quantity)
	every row in entries {
		row.crop == first.crop
		row.quantity == first.quantity
		row.date == first.date
		row.method == first.method
		nonnegative(row.area_ha)
	}
	recorded_ha == sum([r.area_ha | some r in entries])
}

eligible_spreading(e) if {
	spread_log_ok(e)
	not invalid_group_for(e.parcel_id)
	e.method in {"trailing_hose", "trailing_shoe", "injection"}
	technique_ok(e)
	equipment_ok(e)
	eligible_volume(e) > 0
	some p in input.land.parcels
	p.parcel_id == e.parcel_id
	p.land_use in {"arable", "grassland"}
	p.country == "AT"
}

eligible_separation(e) if {
	in_year(e.date)
	e.own_cattle_slurry == true
	e.mechanically_separated_on_farm == true
	nonnegative(e.volume_m3)
	equipment_ok(e)
}

annual_activity if {
	some e in annual.spreading
	eligible_spreading(e)
}

annual_activity if {
	some e in annual.separations
	eligible_separation(e)
	e.volume_m3 > 0
}

annual_activity if feeding_ok

fertilisable(p) if {
	p.land_use in {"arable", "grassland"}
	p.country == "AT"
	p.n_demand_napv == true
	p.pure_legumes == false
	p.total_fertilizer_ban == false
}

area_known(p) if {
	not p.land_use in {"arable", "grassland"}
	is_string(p.land_use)
}

area_known(p) if {
	is_string(p.country)
	p.country != "AT"
}

area_known(p) if {
	p.country == "AT"
	nonnegative(p.area_ha)
	is_boolean(p.n_demand_napv)
	is_boolean(p.pure_legumes)
	is_boolean(p.total_fertilizer_ban)
}

fertilisable_ha := sum([p.area_ha | some p in input.land.parcels; fertilisable(p)]) if {
	is_array(input.land.parcels)
	every p in input.land.parcels { area_known(p) }
}

spread_cap_m3 := 50 * fertilisable_ha

# Ein Bestandssatz ist eine disjunkte Anhang-A-Kategorie im Inland.
head_count(g) := g.annual_average if {
	g.species == "cattle"
	nonnegative(g.annual_average)
}

head_count(g) := g.annual_average if {
	g.species != "cattle"
	g.average_list_submitted == true
	nonnegative(g.annual_average)
}

head_count(g) := g.animal_count if {
	g.species != "cattle"
	g.average_list_submitted == false
	g.fluctuating == false
	nonnegative(g.animal_count)
}

animal_factor(g) := row.factor if {
	row := tables.gve[g.gve_category]
	row.species_group == "cattle"
	g.species == "cattle"
	is_string(g.breed)
	g.breed != ""
	dwarf := g.breed in tables.dwarf_breeds
	startswith(g.gve_category, "dwarf_") == dwarf
}

animal_factor(g) := row.factor if {
	row := tables.gve[g.gve_category]
	row.species_group == "pigs"
	g.species == "pigs"
}

animal_factor(g) := row.factor if {
	row := tables.gve[g.gve_category]
	row.species_group == "other"
	not g.species in {"pigs", "cattle"}
	not g.gve_category in {"red_deer", "other_deer", "camelid", "wild_young"}
}

animal_factor(g) := row.factor if {
	row := tables.gve[g.gve_category]
	g.gve_category in {"red_deer", "other_deer", "camelid", "wild_young"}
	g.annex_a_wild_holding == true
}

in_stock_group(g, group) if g.species == group

in_stock_group(g, "rgve") if g.species in {"cattle", "sheep_goats", "horses"}

in_stock_group(g, "rgve") if {
	g.gve_category in object.keys(tables.gve)
	tables.gve[g.gve_category].rgve
}

gve_total(group) := sum([units |
	some g in input.livestock.species_groups
	in_stock_group(g, group)
	g.country == "AT"
	units := head_count(g) * animal_factor(g)
]) if {
	is_array(input.livestock.species_groups)
	every g in input.livestock.species_groups {
		is_string(g.species)
		stock_known(g, group)
	}
}

stock_known(g, group) if not in_stock_group(g, group)

stock_known(g, group) if {
	in_stock_group(g, group)
	is_string(g.country)
	g.country != "AT"
}

stock_known(g, group) if {
	in_stock_group(g, group)
	g.country == "AT"
	nonnegative(head_count(g))
	nonnegative(animal_factor(g))
}

separation_cap_m3 := 20 * gve_total("cattle")

pig_density_met if {
	is_number(input.land.arable_area_ha)
	input.land.arable_area_ha > 0
	gve_total("pigs") >= input.land.arable_area_ha
}

livestock_farm if {
	ha := input.land.grassland_area_ha + input.land.arable_forage_ha
	ha > 0
	gve_total("rgve") >= 0.30 * ha
}

feed_source_ok(i) if {
	i.kind == "compound"
	i.protein_source == "manufacturer"
}

feed_source_ok(i) if {
	i.kind == "individual"
	i.tested == true
	i.protein_source == "analysis"
}

feed_source_ok(i) if {
	i.kind == "individual"
	i.tested == false
	i.protein_source == "literature"
}

within_limit(r, limit) if {
	nonnegative(r.protein_g_kg_88)
	r.protein_g_kg_88 <= tables.protein[limit]
}

finisher(r) if {
	r.category == "finishing"
	nonnegative(r.weight_kg)
	r.weight_kg >= 32
}

finisher(r) if {
	r.category == "unserved_gilt"
	nonnegative(r.weight_kg)
	r.weight_kg >= 50
}

phase_key(w) := "phase_32" if {
	w >= 32
	w < 60
}

else := "phase_60" if {
	w >= 60
	w < 90
}

else := "phase_90" if w >= 90

ration_ok(r) if {
	r.category == "piglet"
	nonnegative(r.weight_kg)
	r.weight_kg >= 8
	r.weight_kg < 32
	within_limit(r, "piglet_mean")
}

ration_ok(r) if {
	r.category == "pregnant"
	within_limit(r, "pregnant")
}

ration_ok(r) if {
	r.category == "served_gilt"
	nonnegative(r.weight_kg)
	r.weight_kg >= 50
	within_limit(r, "pregnant")
}

ration_ok(r) if {
	r.category == "lactating"
	within_limit(r, "lactating")
}

ration_ok(r) if {
	r.category == "boar"
	nonnegative(r.weight_kg)
	r.weight_kg >= 50
	within_limit(r, "boar")
}

ration_ok(r) if finisher(r)

finisher_limits_ok(f) if every r in f.rations { not finisher(r) }

finisher_limits_ok(f) if {
	some r in f.rations
	finisher(r)
	nonnegative(f.finishing_mean_g_kg_88)
	f.finishing_mean_g_kg_88 <= tables.protein.finishing_mean
}

finisher_limits_ok(f) if {
	f.phase_technically_possible == true
	f.phase_actually_used == true
	every r in f.rations { phase_or_other(r) }
}

phase_or_other(r) if not finisher(r)

phase_or_other(r) if {
	finisher(r)
	within_limit(r, phase_key(r.weight_kg))
}

rations_ok(f) if {
	is_array(f.rations)
	count(f.rations) > 0
	every r in f.rations { ration_ok(r) }
	finisher_limits_ok(f)
}

feeding_ok if {
	program_year
	year >= 2025
	f := annual.feeding
	f.participating == true
	f.groundwater_option == false
	pig_density_met
	f.all_pigs_covered == true
	f.recipes_88_available == true
	count(f.ingredients) > 0
	every i in f.ingredients { feed_source_ok(i) }
	rations_ok(f)
}

feed_amount_eur := rate("feeding") * annual.eligible_arable_ha if {
	feeding_ok
	nonnegative(annual.eligible_arable_ha)
	annual.eligible_arable_ha <= input.land.arable_area_ha
}

# Nachweise und Mengen sind je Verfahren auswertbar. Die gemeinsame Grenze hat
# bei mehreren Sätzen keine in den Quellen festgelegte Zuteilungsreihenfolge.
documented_m3(category) := sum([eligible_volume(e) | some e in annual.spreading; e.method == category; eligible_spreading(e)]) if {
	category in {"trailing_hose", "trailing_shoe", "injection"}
	is_array(annual.spreading)
}

documented_m3("separation") := sum([e.volume_m3 | some e in annual.separations; eligible_separation(e)]) if is_array(annual.separations)

claim_basis(c) := min([claimed_volume(c), documented_m3(c)])

claim_basis(c) := 0 if {
	annual.claims_complete == true
	is_object(annual.claims)
	not c in object.keys(annual.claims)
}

separation_amount_eur := min([claim_basis("separation"), separation_cap_m3]) * rate("separation")
spread_basis := {c: claim_basis(c) | some c in ["trailing_hose", "trailing_shoe", "injection"]}
spread_payable_m3 := min([spread_cap_m3, sum([v | some _, v in spread_basis])]) if count(spread_basis) == 3

spread_amount_eur := sum([amount | some c, v in spread_basis; amount := v * rate(c)]) if {
	count(spread_basis) == 3
